const fs=require('fs'),cp=require('child_process'),path=require('path'),crypto=require('crypto');
const dir='Z:/00.Roboti/EVA.Pro/Eva-contab/Audit_P01_2026-11-01',dest=path.join(dir,'executie/A02');fs.mkdirSync(dest,{recursive:true});const plan=require(dir+'/A02_plan.json');const names=Array.from(new Set(plan.inventory.table_groups.flatMap(g=>g.tables.map(n=>n.toLowerCase()))));const arr='ARRAY['+names.map(x=>"'"+x+"'").join(',')+']';
const queries={
baseline:`SELECT current_database() AS db,current_schema() AS first_schema,version() AS pg,current_setting('transaction_read_only') AS readonly,(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='adempiere' AND c.relkind IN ('r','p','v','m')) AS relations`,
taxonomy:`SELECT n.table_name, t.ad_table_id,t.tablename,t.entitytype,t.isactive,t.accesslevel,t.ischangelog,c.relkind FROM unnest(${arr}) AS n(table_name) LEFT JOIN adempiere.ad_table t ON lower(t.tablename)=n.table_name LEFT JOIN pg_class c ON c.oid=to_regclass('adempiere.'||n.table_name) ORDER BY n.table_name,t.ad_table_id`,
physical:`SELECT table_name,column_name,data_type,udt_name,character_maximum_length,numeric_precision,numeric_scale,is_nullable,column_default FROM information_schema.columns WHERE table_schema='adempiere' AND table_name=ANY(${arr}) ORDER BY table_name,ordinal_position`,
dictionary:`SELECT lower(t.tablename) AS table_name,lower(c.columnname) AS column_name,c.ad_column_id,c.ad_reference_id,c.fieldlength,c.ismandatory,c.iskey,c.isidentifier,c.isactive,c.entitytype,c.isencrypted,(NULLIF(trim(c.columnsql),'') IS NOT NULL) AS is_virtual FROM adempiere.ad_table t JOIN adempiere.ad_column c ON c.ad_table_id=t.ad_table_id WHERE lower(t.tablename)=ANY(${arr}) ORDER BY lower(t.tablename),lower(c.columnname)`,
constraints:`SELECT c.relname AS table_name,x.conname,x.contype,x.convalidated,x.condeferrable,pg_get_constraintdef(x.oid) AS definition FROM pg_constraint x JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='adempiere' AND c.relname=ANY(${arr}) ORDER BY c.relname,x.conname`,
indexes:`SELECT c.relname AS table_name,i.relname AS index_name,x.indisunique,x.indisvalid,x.indisready,pg_get_indexdef(i.oid) AS definition FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class c ON c.oid=x.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='adempiere' AND c.relname=ANY(${arr}) ORDER BY c.relname,i.relname`,
triggers:`SELECT c.relname AS table_name,t.tgname,t.tgenabled,t.tgisinternal,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='adempiere' AND c.relname=ANY(${arr}) ORDER BY c.relname,t.tgname`,
rules:`SELECT schemaname,tablename,rulename,definition FROM pg_rules WHERE schemaname='adempiere' AND tablename=ANY(${arr}) ORDER BY tablename,rulename`,
processes:`SELECT value,classname,isactive,count(*) AS rows FROM adempiere.ad_process WHERE lower(value) IN ('eva_notasetwms','eva_activarewms') OR lower(classname) LIKE '%importinventar%' GROUP BY value,classname,isactive ORDER BY value`,
forms:`SELECT classname,isactive,count(*) AS rows FROM adempiere.ad_form WHERE lower(classname) LIKE ANY(ARRAY['%wgestiunewmsform','%wsagagestiuniform','%wproduseform','%winventarform']) GROUP BY classname,isactive ORDER BY classname`,
table_identity:`SELECT tablename,accesslevel,isview,entitytype,ischangelog FROM adempiere.ad_table WHERE lower(tablename) IN ('m_product','m_inventoryline','eva_stocwms','eva_miscarewms','eva_jurnalaprobare','eva_jurnalapisite') ORDER BY tablename`,
catalog_capabilities:`SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='adempiere' AND (column_name ~* '(tombstone|neverreuse|nereutil|eva_(cpp|cpa)|product_identity|identitateprodus)' OR table_name ~* '(tombstone|neverreuse|nereutil|product_identity|identitateprodus)') ORDER BY table_name,column_name`,
product_fields:`SELECT column_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='adempiere' AND table_name='m_product' AND (column_name LIKE 'eva_%' OR column_name='m_product_uu' OR column_name IN ('value','upc','sku','m_product_id')) ORDER BY column_name`,
storage_ref:`SELECT c.relname AS table_name,count(*) AS physical_columns,(SELECT count(*) FROM adempiere.ad_column ac JOIN adempiere.ad_table at ON at.ad_table_id=ac.ad_table_id WHERE lower(at.tablename)=c.relname AND ac.isactive='Y') AS active_ad_columns FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE n.nspname='adempiere' AND c.relname IN ('m_product','eva_stocwms','eva_perechewms','eva_miscarewms','m_inventorylinema','m_storagereservation') GROUP BY c.relname ORDER BY c.relname`};
const remote=`docker exec -i eva-postgres-cesiro sh -c 'exec psql -X -qAt -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d idempiere'`;
const script=`BEGIN READ ONLY;\nSET LOCAL statement_timeout='12s';\nSET LOCAL search_path TO adempiere,pg_catalog,public;\n`+Object.entries(queries).map(([id,q])=>`SELECT json_build_object('id','${id}','rows',COALESCE(json_agg(row_to_json(r)),'[]'::json))::text FROM (${q}) r;`).join('\n')+'\nROLLBACK;';
const output=cp.execFileSync('ssh',['-o','BatchMode=yes','-o','ConnectTimeout=8','-o','StrictHostKeyChecking=yes','saga-server@192.168.100.151',remote],{input:script,encoding:'utf8',maxBuffer:56*1024*1024});let data=Object.fromEntries(output.trim().split('\n').map(l=>{let x=JSON.parse(l);return[x.id,x.rows]}));const artifact={timestamp:new Date().toISOString(),id:'EV-A02-CESIRO-META',scope:'Catalog tehnic CESIRO; niciun rând business sau PII extras.',transaction:'BEGIN READ ONLY / ROLLBACK; search_path adempiere,pg_catalog,public; statement_timeout 12s',sha:plan.baseline.git_sha,queries,data};fs.writeFileSync(path.join(dest,'CESIRO_metadate.json'),JSON.stringify(artifact)+'\n');console.log(JSON.stringify({counts:Object.fromEntries(Object.entries(data).map(([k,v])=>[k,v.length])),baseline:data.baseline,missing:data.taxonomy.filter(r=>!r.relkind).map(r=>r.table_name),wms:data.storage_ref,process:data.processes,forms:data.forms,productextra:data.product_fields,cap:data.catalog_capabilities.length}));
